#include <vector>

// hidden test helpers: nest opens one block inside another for each cap and records the limit
// on the way in and after each inner block closes; siblings opens one block at a time
void nest_from(int& lim, const std::vector<int>& caps, std::size_t i, std::vector<int>& r) {
    TempLimit t(lim, caps[i]);
    r.push_back(lim);
    if (i + 1 < caps.size()) { nest_from(lim, caps, i + 1, r); r.push_back(lim); }
}
std::vector<int> nest(int start, const std::vector<int>& caps) {
    int lim = start;
    std::vector<int> r;
    if (!caps.empty()) nest_from(lim, caps, 0, r);
    r.push_back(lim);
    return r;
}
std::vector<int> siblings(int start, const std::vector<int>& caps) {
    int lim = start;
    std::vector<int> r;
    for (int c : caps) { { TempLimit t(lim, c); r.push_back(lim); } r.push_back(lim); }
    return r;
}

